pub(crate) fn sv_back_substituted(values: &collections::BTreeMap<String, i64>, solved: &[SvSolved], names: &[String]) -> Option<collections::BTreeMap<String, i64>> {
    let mut out = values.copy_owned();
    let mut i = solved.len() as i64;
    while i > 0 {
        i = unsafe { nikaia_std::proven::sub::<i64>(i, 1) };
        let s = (*unsafe { nikaia_std::proven::read(&solved, (i) as usize) }).clone();
        let mut rest: i64 = s.row.constant;
        let mut unit: i64 = 0;
        let mut j: i64 = 0;
        while ((j) as usize) < s.row.cols.len() {
            let c = *unsafe { nikaia_std::proven::read(&s.row.cols, (j) as usize) };
            if c == s.column { unit = *nikaia_std::index::get(&s.row.ks, (j) as usize); } else {
                let v: i64 = nikaia_std::index::or(out.get(&sv_column_name(c, names)), || 0);
                rest = match rest.checked_add(match (*nikaia_std::index::get(&s.row.ks, (j) as usize)).checked_mul(v) { Some(__nikaia_value) => __nikaia_value, None => return None }) { Some(__nikaia_value) => __nikaia_value, None => return None };
            }
            j = unsafe { nikaia_std::proven::add::<i64>(j, 1) };
        }
        if unit != 1 && unit != -1 { return None; }
        let value = if unit == 1 { match rest.checked_neg() { Some(__nikaia_value) => __nikaia_value, None => return None } } else { rest };
        out.insert(sv_column_name(s.column, names), value);
    }
    Some(out)
}

#[cfg(test)]
pub(crate) fn sv_theory_test_answer_kind(answer: &LgAnswer) -> String {
    match answer {
        LgAnswer::Proved { .. } => String::from("proved"),
        LgAnswer::Refuted { .. } => String::from("refuted"),
        LgAnswer::Unknown { why } => sv_unknown(why),
    }
}

#[cfg(test)]
pub(crate) fn sv_theory_test_both(name: &str, source: &str) -> String {
    let script = match lg_smtlib_read(source) {
        LgRead::Script(ref s) => s.clone(),
        LgRead::Failed(_) => { return format!("{}: unreadable\n", name); },
    };
    let mut arena = script.arena.clone();
    let goal = arena.boolean(false);
    let budget = lg_budget();
    let old = sv_theory_test_answer_kind(&lg_check(&arena, &script.assertions, goal, &budget));
    let run = sv_smt_engine(&arena, &script.assertions, goal, &budget, String::from("fm"));
    let new = match run.driven {
        SvDriven::Proved(ref query, ref steps) => {
            let v = sv_check(query, steps);
            if v.ok { format!("proved, log of {} steps checked", steps.len() as i64) } else { format!("log rejected: {}", v.reason) }
        },
        SvDriven::Answer(ref answer) => sv_theory_test_answer_kind(answer),
        SvDriven::RealModel(_) => String::from("refuted"),
    };
    format!("{}: lg_check {}; interface {}\n", name, old, new)
}

